import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

function Dashboard() {
    const [user, setUser] = useState(null);
    const [alimentos, setAlimentos] = useState([]);
    const [solicitacoes, setSolicitacoes] = useState([]);
    const [minhasSolicitacoes, setMinhasSolicitacoes] = useState([]);
    const navigate = useNavigate();

    const [novoAlimento, setNovoAlimento] = useState({
        nome: '',
        dataValidade: '',
        quantidadeTotal: 0,
        unidadeMedida: 'KG'
    });

    useEffect(() => {
        const loggedUser = JSON.parse(localStorage.getItem('user'));
        if (!loggedUser) {
            navigate('/');
        } else {
            setUser(loggedUser);
            // Carregamento inicial de dados
            carregarDadosIniciais(loggedUser);
        }
    }, [navigate]);

    // Função centralizadora para evitar chamadas desencontradas
    const carregarDadosIniciais = (usuario) => {
        carregarAlimentos();
        if (usuario.tipoUsuario === 'DOADOR') {
            carregarSolicitacoes(usuario.id);
        } else if (usuario.tipoUsuario === 'RECEPTOR') {
            carregarMinhasSolicitacoes(usuario.id);
        }
    };

    const carregarAlimentos = async () => {
        try {
            const response = await api.get('/alimento/disponiveis');
            setAlimentos(response.data || []);
        } catch (err) {
            console.error("Erro ao carregar alimentos", err);
        }
    };

    const carregarSolicitacoes = async (userId) => {
        const id = userId || user?.id;
        if (!id) return;
        try {
            const response = await api.get(`/solicitacao/pendentes/${id}`);
            setSolicitacoes(response.data || []);
        } catch (err) {
            console.error("Erro ao carregar solicitações pendentes", err);
        }
    };

    const carregarMinhasSolicitacoes = async (userId) => {
        const id = userId || user?.id;
        if (!id) return;
        try {
            const response = await api.get(`/solicitacao/minhas-solicitacoes/${id}`);
            setMinhasSolicitacoes(response.data || []);
        } catch (err) {
            console.error("Erro ao carregar minhas solicitações", err);
        }
    };

    const handleCadastrarAlimento = async (e) => {
        e.preventDefault();
        try {
            await api.post(`/alimento/registrar/${user.id}`, novoAlimento);
            alert("Alimento cadastrado com sucesso!");
            setNovoAlimento({ nome: '', dataValidade: '', quantidadeTotal: 0, unidadeMedida: 'KG' });
            carregarAlimentos();
        } catch (err) {
            alert("Erro ao cadastrar: " + (err.response?.data?.message || err.message));
        }
    };

    const handleSolicitar = async (alimentoId) => {
        const alimentoAlvo = alimentos.find(a => a.id === alimentoId);
        if (!alimentoAlvo) return;

        // CORREÇÃO: Usar "-" em vez de "=" para calcular disponibilidade
        const qtdDisponivel = alimentoAlvo.quantidadeTotal - (alimentoAlvo.quantidadeReservada || 0);

        const quantidadeStr = prompt(`Quantos itens deseja solicitar? (Disponível: ${qtdDisponivel})`);
        if (!quantidadeStr) return;

        const quantidade = parseInt(quantidadeStr);
        if (isNaN(quantidade) || quantidade <= 0) {
            alert("Quantidade inválida.");
            return;
        }

        if (quantidade > qtdDisponivel) {
            alert("Quantidade superior ao estoque disponível!");
            return;
        }

        const descricao = prompt("Informe o motivo da solicitação:");
        if (!descricao || descricao.trim() === "") {
            alert("O motivo é obrigatório!");
            return;
        }

        try {
            const payload = {
                receptorId: user.id, // Verifique se seu DTO no backend espera 'receptorId' ou apenas 'id'
                quantidade: quantidade,
                descricao: descricao,
                alimento: { id: alimentoId }
            };

            await api.post('/solicitacao/criar', payload);
            alert("Solicitação enviada!");
            carregarAlimentos();
            carregarMinhasSolicitacoes(user.id);
        } catch (err) {
            alert("Erro ao solicitar: " + (err.response?.data?.message || err.message));
        }
    };

    const handleAprovar = async (idSolicitacao) => {
        try {
            await api.post(`/solicitacao/aprovar/${user.id}?idSolicitacao=${idSolicitacao}`);
            alert("Solicitação aprovada!");
            carregarSolicitacoes(user.id);
            carregarAlimentos();
        } catch (err) {
            alert("Erro ao aprovar.");
        }
    };

    const handleRecusar = async (idSolicitacao) => {
        try {
            await api.post(`/solicitacao/recusar/${user.id}?idSolicitacao=${idSolicitacao}`);
            alert("Solicitação recusada.");
            carregarSolicitacoes(user.id);
        } catch (err) {
            alert("Erro ao recusar.");
        }
    };

    const handleLogout = () => {
        localStorage.removeItem('user');
        navigate('/');
    };

    if (!user) return null;

    return (
        <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
            <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <h1>Food Care - Painel {user.tipoUsuario}</h1>
                <button onClick={handleLogout} style={{ padding: '5px 15px', cursor: 'pointer' }}>Sair</button>
            </header>

            <hr />

            {/* PAINEL DOADOR */}
            {user.tipoUsuario === 'DOADOR' && (
                <>
                    <section style={{ backgroundColor: '#f4f4f4', padding: '20px', borderRadius: '8px', marginBottom: '20px' }}>
                        <h3>+ Cadastrar Novo Alimento</h3>
                        <form onSubmit={handleCadastrarAlimento} style={{ display: 'flex', gap: '10px' }}>
                            <input type="text" placeholder="Nome" value={novoAlimento.nome} onChange={(e) => setNovoAlimento({ ...novoAlimento, nome: e.target.value })} required />
                            <input type="date" value={novoAlimento.dataValidade} onChange={(e) => setNovoAlimento({ ...novoAlimento, dataValidade: e.target.value })} required />
                            <input type="number" placeholder="Qtd" value={novoAlimento.quantidadeTotal} onChange={(e) => setNovoAlimento({ ...novoAlimento, quantidadeTotal: e.target.value })} required />
                            <button type="submit" style={{ backgroundColor: '#28a745', color: 'white', border: 'none', padding: '8px 15px', borderRadius: '4px', cursor: 'pointer' }}>Salvar Doação</button>
                        </form>
                    </section>

                    <section>
                        <h3>Solicitações Recebidas</h3>
                        {solicitacoes.length === 0 ? <p>Nenhuma solicitação pendente.</p> : (
                            <table border="1" cellPadding="10" style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                                <thead style={{ backgroundColor: '#eee' }}>
                                    <tr>
                                        <th>Alimento</th>
                                        <th>Quantidade</th>
                                        <th>Motivo</th>
                                        <th>Ações</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {solicitacoes.map(sol => (
                                        <tr key={sol.id}>
                                            <td>{sol.nomeAlimento || 'Alimento'}</td>
                                            <td>{sol.quantidade}</td>
                                            <td>{sol.descricao || 'Não informado'}</td>
                                            <td>
                                                <button onClick={() => handleAprovar(sol.id)} style={{ backgroundColor: '#007bff', color: 'white', border: 'none', padding: '5px 10px', borderRadius: '4px', marginRight: '5px', cursor: 'pointer' }}>Aprovar</button>
                                                <button onClick={() => handleRecusar(sol.id)} style={{ backgroundColor: '#dc3545', color: 'white', border: 'none', padding: '5px 10px', borderRadius: '4px', cursor: 'pointer' }}>Recusar</button>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        )}
                    </section>
                </>
            )}

            {/* PAINEL RECEPTOR */}
            {user.tipoUsuario === 'RECEPTOR' && (
                <>
                    <section>
                        <h3>Alimentos Disponíveis</h3>
                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: '15px' }}>
                            {alimentos.map(alimento => (
                                <div key={alimento.id} style={{ border: '1px solid #ddd', padding: '15px', borderRadius: '8px' }}>
                                    <h4>{alimento.nome}</h4>
                                    <p>Validade: {alimento.dataValidade}</p>
                                    <p><strong>Disponível: {alimento.quantidadeTotal - (alimento.quantidadeReservada || 0)}</strong></p>
                                    <button onClick={() => handleSolicitar(alimento.id)} style={{ width: '100%', padding: '8px', backgroundColor: '#28a745', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>Solicitar</button>
                                </div>
                            ))}
                        </div>
                    </section>

                    <section style={{ marginTop: '30px' }}>
                        <h3>Minhas Solicitações</h3>
                        <table border="1" cellPadding="10" style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                            <thead style={{ backgroundColor: '#eee' }}>
                                <tr>
                                    <th>Alimento</th>
                                    <th>Qtd</th>
                                    <th>Status</th>
                                </tr>
                            </thead>
                            <tbody>
                                {minhasSolicitacoes.map(sol => (
                                    <tr key={sol.id}>
                                        <td>{sol.nomeAlimento || 'Item'}</td>
                                        <td>{sol.quantidade}</td>
                                        <td style={{ 
                                            fontWeight: 'bold', 
                                            color: sol.status === 'APROVADA' ? 'green' : sol.status === 'RECUSADA' ? 'red' : 'orange' 
                                        }}>{sol.status}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </section>
                </>
            )}
        </div>
    );
}

export default Dashboard;
